# PW04 common library (literature + exact/numeric replay only).  python3 -I; numpy/scipy/mpmath.
import mpmath as mp, numpy as np, json, sys, hashlib
mp.mp.dps = 80
MPF = mp.mpf

# ---------- nodes / parameters ----------
def cheb_nodes(s):                      # BIT (5.8): c_i = cos((2s+1-2i)pi/(2s)) / cos(pi/(2s))
    return [mp.cos((2*s+1-2*i)*mp.pi/(2*s))/mp.cos(mp.pi/(2*s)) for i in range(1, s+1)]
def sigma_sup(s):                       # BIT Remark 2.1 : (s-2) x^(s-1) - (s-1) x^(s-2) - 1 = 0, root > 1
    f = lambda x: (s-2)*x**(s-1) - (s-1)*x**(s-2) - 1
    lo, hi = MPF(1), MPF(4)             # f(1) = -2 < 0 ; f(4) > 0 for s>=3
    for _ in range(300):
        mid = (lo+hi)/2
        if f(mid) > 0: hi = mid
        else: lo = mid
    return (lo+hi)/2
def g1_of(s): return 1 - 1/sigma_sup(s)  # (1-g1) sigma_sup = 1

# ---------- Route 1: BIT matrix formulas (2.4),(2.5) : Theta = V S P V^-1, E = V D F0^T V^-1, B = Theta - sigma A E ----------
def vander(c):
    s = len(c); return mp.matrix([[c[i]**j for j in range(s)] for i in range(s)])
def route1(c, gam, sg):
    s = len(c); V = vander(c); Vi = V**-1
    S = mp.diag([sg**j for j in range(s)])
    P = mp.matrix(s, s)
    for i in range(s):
        for j in range(i, s): P[i, j] = mp.binomial(j, i)
    D = mp.diag([k+1 for k in range(s)])
    F0 = mp.matrix(s, s)
    for i in range(1, s): F0[i, i-1] = 1
    Th = V*S*P*Vi
    E = V*D*F0.T*Vi
    G = mp.diag(gam)
    Gm = -G*Th; A = -Gm
    B = Th - sg*A*E
    return dict(Theta=Th, Gamma=Gm, A=A, B=B, E=E)

# ---------- Route 2: direct Lagrange/polynomial form of Gamma(s),AB(s)  (BIT (3.1)); no Vandermonde inverse ----------
def lag(c, j, x):
    r = MPF(1)
    for k in range(len(c)):
        if k != j: r *= (x-c[k])/(c[j]-c[k])
    return r
def dlag(c, j, x):
    s = len(c); tot = MPF(0)
    for m in range(s):
        if m == j: continue
        t = 1/(c[j]-c[m])
        for k in range(s):
            if k != j and k != m: t *= (x-c[k])/(c[j]-c[k])
        tot += t
    return tot
def route2(c, gam, sg):
    s = len(c); Th = mp.matrix(s, s); B = mp.matrix(s, s); A = mp.matrix(s, s)
    for i in range(s):
        x = 1+sg*c[i]
        for j in range(s):
            Th[i, j] = lag(c, j, x)
            A[i, j] = gam[i]*Th[i, j]                       # A = -Gamma = G Theta
            B[i, j] = Th[i, j] - gam[i]*sg*dlag(c, j, x)    # (3.1) AB: b_ij p(c_j) = p(1+sg c_i) - gam_i sg p'(1+sg c_i)
    return dict(Theta=Th, A=A, B=B)

# ---------- Route 3: BIT (2.15)  B~ = (I - g1 Dhat - g0 F0^T Dhat) S P, B = V B~ V^-1 ----------
def route3(c, g0, g1, sg):
    s = len(c); V = vander(c); Vi = V**-1
    S = mp.diag([sg**j for j in range(s)])
    P = mp.matrix(s, s)
    for i in range(s):
        for j in range(i, s): P[i, j] = mp.binomial(j, i)
    Dh = mp.diag([k for k in range(s)])
    F0 = mp.matrix(s, s)
    for i in range(1, s): F0[i, i-1] = 1
    Bt = (mp.eye(s) - g1*Dh - g0*F0.T*Dh)*S*P
    return dict(Btilde=Bt, B=V*Bt*Vi, V=V, Vi=Vi)

def mdiff(X, Y): return max(abs(X[i, j]-Y[i, j]) for i in range(X.rows) for j in range(X.cols))
def mp2np(M): return np.array([[float(M[i, j]) for j in range(M.cols)] for i in range(M.rows)])

# ---------- (4.7) superconvergence condition on g0 ----------
def v_tilde(s, g0, g1):                 # left eigvec (size s+1) of the (s+1)x(s+1) triangular B~(sigma=1), eigenvalue 1, v1=1
    n = s+1
    S = mp.eye(n); P = mp.matrix(n, n)
    for i in range(n):
        for j in range(i, n): P[i, j] = mp.binomial(j, i)
    Dh = mp.diag([k for k in range(n)]); F0 = mp.matrix(n, n)
    for i in range(1, n): F0[i, i-1] = 1
    Bt = (mp.eye(n) - g1*Dh - g0*F0.T*Dh)*S*P
    v = [MPF(0)]*n; v[0] = MPF(1)
    for j in range(1, n):
        acc = sum(v[i]*Bt[i, j] for i in range(j))
        v[j] = acc/(1-Bt[j, j])           # v_j (B~_jj - 1) + sum_{i<j} v_i B~_ij = 0
    return v
def resid47(c, g0, g1):                  # (4.7): v~ . (phi_0..phi_{s-1}, 1)
    s = len(c); v = v_tilde(s, g0, g1)
    # node polynomial coefficients phi_0..phi_s (phi_s = 1)
    co = [MPF(1)]
    for ci in c:
        new = [MPF(0)]*(len(co)+1)
        for k, a in enumerate(co): new[k+1] += a; new[k] -= ci*a
        co = new
    return sum(v[k]*co[k] for k in range(s+1))
def g0_roots_47(c, g1, lo=None, hi=4, n=800):
    # roots of a polynomial in g0 (degree <= s): interpolate exactly through s+1 points, then polyroots
    s = len(c); pts = [MPF(k)/2 for k in range(s+1)]
    vals = [resid47(c, p, g1) for p in pts]
    # Newton-form -> monomial via solving Vandermonde
    Vm = mp.matrix([[p**k for k in range(s+1)] for p in pts]); co = mp.lu_solve(Vm, mp.matrix(vals))
    rts = mp.polyroots([co[k] for k in range(s, -1, -1)], maxsteps=500, extraprec=400)
    return sorted([mp.re(r) for r in rts if abs(mp.im(r)) < mp.mpf(10)**-40], key=lambda x: x)
# alternative route for g0 :  v^T w = 0 with v left eigvec (v^T 1 = 1) of nodal B(1) and w_i = phi(1+c_i) - gam_i phi'(1+c_i)   (BIT (4.5))
def resid_nodal(c, g0, g1):
    s = len(c); gam = [g0+g1*ci for ci in c]
    B = route2(c, gam, MPF(1))['B']
    Bn = mp2np(B)
    # left eigenvector for eigenvalue 1 by exact solve in mp:  v^T (B - I) = 0, v^T 1 = 1
    M = (B - mp.eye(s)).T
    M2 = mp.matrix(s, s)
    for i in range(s-1):
        for j in range(s): M2[i, j] = M[i, j]
    for j in range(s): M2[s-1, j] = 1
    rhs = mp.matrix([0]*(s-1)+[1]); v = mp.lu_solve(M2, rhs)
    phi = lambda x: mp.fprod([x-ci for ci in c])
    dphi = lambda x: mp.fsum(mp.fprod([x-ck for k, ck in enumerate(c) if k != m]) for m in range(s))
    w = [phi(1+c[i]) - gam[i]*dphi(1+c[i]) for i in range(s)]
    return mp.fsum(v[i]*w[i] for i in range(s))

# ---------- numpy (double) coefficient evaluation for experiments ----------
def lag_np(c, x):
    s = len(c); L = np.ones((len(x), s)); dL = np.zeros((len(x), s))
    for j in range(s):
        for k in range(s):
            if k != j: L[:, j] *= (x-c[k])/(c[j]-c[k])
        for m in range(s):
            if m == j: continue
            t = np.ones(len(x))/(c[j]-c[m])
            for k in range(s):
                if k != j and k != m: t *= (x-c[k])/(c[j]-c[k])
            dL[:, j] += t
    return L, dL
def coef_np(c, gam, sg):
    c = np.asarray(c, float); gam = np.asarray(gam, float)
    x = 1+sg*c; L, dL = lag_np(c, x)
    A = gam[:, None]*L; B = L - gam[:, None]*sg*dL
    return B, A
def alpha_deg(B, gam, nphi=721, nr=500, rlo=-6, rhi=10):
    rs = np.logspace(rlo, rhi, nr); g = np.asarray(gam, float)
    def f(p):
        z = rs*np.exp(1j*(np.pi-np.radians(p)))
        M = (1.0/(1.0-z[:, None]*g[None, :]))[:, :, None]*B[None, :, :]
        return float(np.max(np.abs(np.linalg.eigvals(M))))
    prev = 0.0
    for p in np.linspace(0, 90, nphi):
        if f(p) >= 1+1e-13:
            lo, hi = prev, p
            for _ in range(40):
                m = 0.5*(lo+hi)
                if f(m) >= 1+1e-13: hi = m
                else: lo = m
            return lo
        prev = p
    return 90.0
def rho(M): return float(np.max(np.abs(np.linalg.eigvals(M))))

# ---------- method definitions ----------
P26 = dict(c=["-1.702","-0.51","-0.195797762","0.155193392","0.755672784","1"],
  g0=["0.214789562","0.249182503","0.237832565","0.245204742","0.353848357"],
  g1=["0.566334104","0.496228487","0.518584061","0.498857638","0.502412430"])   # APNUM 48 PPSW2-6 (PW03A/PW03B recovery)
def gam_ppsw2(c, g0, g1, sg):            # APNUM (3.8) i<s ; (3.6) i=s
    s = len(c); g = [g0[i]/(1+sg*g1[i]) for i in range(s-1)]
    g.append(1/(sg*sum(1/(1+sg-cj) for cj in c))); return g
def mipeer_params(s, g0=None):
    c = cheb_nodes(s); g1 = g1_of(s)
    if g0 is None:
        rts = g0_roots_47(c, g1); lb = -g1*min(c)
        g0 = [r for r in rts if r > lb][0]
    return c, g0, g1
def sha(b): return hashlib.sha256(b if isinstance(b, bytes) else b.encode()).hexdigest()
# PW04-M4: zero-stability of mipeer6 (BIT Thm 2.2, Remark 2.1) : spectra, Theorem-2.2 constant K(sigma_bar), product tests up to and beyond sigma_bar.
from math import comb
mp.mp.dps = 60
out = {}
def setup(s):
    c, g0, g1 = mipeer_params(s); cn = np.array([float(x) for x in c]); return c, cn, float(g0), float(g1)
def Btil(s, g0, g1, sg):                 # closed form (2.15) in double, 0-based
    Bt = np.zeros((s, s))
    for i in range(s):
        for j in range(i, s):
            Bt[i, j] += (1-i*g1)*sg**i*comb(j, i)
            if i+1 <= j: Bt[i, j] -= g0*(i+1)*sg**(i+1)*comb(j, i+1)
    return Bt
def Bbar(s, g0, g1, sbar):               # entrywise majorant of |B~(sigma)|, 0<sigma<=sbar  (each monomial term is increasing in sigma)
    Bb = np.zeros((s, s))
    for i in range(s):
        for j in range(i, s):
            Bb[i, j] += abs(1-i*g1)*sbar**i*comb(j, i)
            if i+1 <= j: Bb[i, j] += g0*(i+1)*sbar**(i+1)*comb(j, i+1)
    return Bb
s = 6; c, cn, g0, g1 = setup(s); gam = g0+g1*cn
V = np.vander(cn, s, increasing=True); Vi = np.linalg.inv(V)
# (a) closed-form B~ vs V^-1 B V
chk = {}
for sg in (0.3, 1.0, 1.25):
    B, A = coef_np(cn, gam, sg); chk[str(sg)] = float(np.abs(Vi@B@V - Btil(s, g0, g1, sg)).max())
out["Btilde_closed_form_vs_Vinv_B_V(maxabs, double)"] = chk
# (b) pointwise spectrum
sup = float(sigma_sup(s)); rows = []
for sg in np.round(np.arange(0.05, 2.0001, 0.05), 3):
    B, A = coef_np(cn, gam, sg); ev = sorted(abs(np.linalg.eigvals(B)))[::-1]
    form = max(sg**i*abs(1-i*g1) for i in range(1, s))
    rows.append(dict(sigma=float(sg), rho_nonunit_numeric=ev[1], rho_nonunit_formula=form))
out["pointwise_nonunit_spectral_radius"] = rows
out["sigma_sup"] = sup
out["binding_indices_at_sigma_sup"] = dict(i2=sup*(1-g1), i6=sup**5*abs(1-5*g1))
# (c) Theorem 2.2 constant:  ||B_m ... B_{m-k}||_inf <= kappa_inf(V) * sup_k ||Bbar^{k+1}||_inf
def Kconst(s, g0, g1, sbar, kmax=4000):
    c = cheb_nodes(s); V = np.array([[float(x**j) for j in range(s)] for x in c]); kap = np.linalg.norm(V, np.inf)*np.linalg.norm(np.linalg.inv(V), np.inf)
    Bb = Bbar(s, g0, g1, sbar); M = np.eye(s); best = 0.0
    for k in range(1, kmax+1):
        M = M@Bb; best = max(best, np.linalg.norm(M, np.inf))
        if k > 50 and best*1e-12 > 1e300: break
    return float(kap), float(best), float(kap*best)
Kt = {}
for s_ in (3, 4, 5, 6):
    c_, cn_, g0_, g1_ = setup(s_); supS = float(sigma_sup(s_))
    printed = {3: 2.0, 4: 1.4, 5: 1.3}.get(s_)
    sbars = sorted(set([x for x in (1.05, 1.1, 1.15, 1.2, 1.25, 1.3, 1.4, 1.5, 2.0) if x < supS] + ([printed] if printed else []) + [round(0.9*supS, 4), round(0.95*supS, 4), round(0.99*supS, 4)]))
    Kt[str(s_)] = dict(sigma_sup=supS, g0=g0_, g1=g1_, rows=[dict(sigma_bar=sb, ratio_to_sup=round(sb/supS, 4), kappa_inf_V=Kconst(s_, g0_, g1_, sb)[0], sup_norm_Bbar_pow=Kconst(s_, g0_, g1_, sb)[1], K=Kconst(s_, g0_, g1_, sb)[2], printed_sigma_bar=(sb == printed)) for sb in sbars])
out["Theorem_2_2_constant_K_vs_sigma_bar"] = Kt
# (d) product tests on the NODAL matrices B(sigma) (double)
rng = np.random.default_rng(20261111)
Bc = {}
def Bs(sg):
    k = round(sg, 9)
    if k not in Bc: Bc[k] = coef_np(cn, gam, sg)[0]
    return Bc[k]
def run_random(lo, hi, L=1000, trials=20):
    worst = 0.0
    for t in range(trials):
        P = np.eye(s)
        for m in range(L):
            P = Bs(rng.uniform(lo, hi))@P; worst = max(worst, np.linalg.norm(P, np.inf))
    return worst
pr = {}
for hi in (1.1, 1.2, 1.3, 1.329, 1.4, 1.5, 2.0):
    pr[f"U[0.05,{hi}]"] = run_random(0.05, hi)
for hi in (1.2, 1.3):
    pr[f"U[{1/hi:.4f},{hi}] (reciprocal-symmetric)"] = run_random(1/hi, hi)
out["random_iid_products_max_norm_inf_over_k<=1000,20_trials"] = pr
# vertex / periodic words with sustained growth: constant sigma and (sigma,sigma,...,1/sigma^r) patterns
cs = {}
for sg in (1.2, 1.3, 1.329, 1.335, 1.35, 1.4):
    P = np.eye(s); mx = 0; hist = []
    for n in range(1, 401):
        P = Bs(sg)@P; mx = max(mx, np.linalg.norm(P, np.inf))
        if n in (50, 100, 200, 400): hist.append(float(np.linalg.norm(P, np.inf)))
    cs[str(sg)] = dict(max_norm_over_400=float(mx), norm_at_50_100_200_400=hist, predicted_rho_nonunit=max(sg**i*abs(1-i*g1) for i in range(1, s)))
out["constant_sigma_products"] = cs
per = {}
for r in (1, 2, 3, 5, 10):
    for sg in (1.3, 1.329, 1.4, 1.5):
        word = [sg]*r+[1/sg**r]; P = np.eye(s); mx = 0
        for rep in range(400):
            for x in word: P = Bs(x)@P; mx = max(mx, np.linalg.norm(P, np.inf))
        per[f"({sg})^{r},{1/sg**r:.4g}"] = dict(max_norm=float(mx), final_norm=float(np.linalg.norm(P, np.inf)))
out["periodic_words_sigma^r_then_1/sigma^r(zero net growth)"] = per
# word search lower bound of JSR on the nonunit quotient: use full word spectra (finite alphabet, length<=6); compare with triangular prediction
import itertools
def quot(B):
    S = np.eye(s); S[:, 0] = 1.0; M = np.linalg.solve(S, B@S); return M[1:, 1:]
alph = [0.1, 0.8, 1.0, 1.2, 1.329]
Qc = {x: quot(Bs(x)) for x in alph}
worst = {}
for L in range(1, 6):
    w = 0.0; wword = None
    for word in itertools.product(alph, repeat=L):
        P = np.eye(s-1)
        for x in word: P = Qc[x]@P
        r = rho(P)**(1.0/L)
        if r > w: w, wword = r, word
    worst[str(L)] = dict(max_rho_pow=w, word=list(wword))
out["word_search_quotient_rho_pow_alphabet{0.1,0.8,1,1.2,1.329}_L<=5"] = worst
# stage-pair exact statement: spectrum of any product = product of diagonals (triangular B~)
P = np.eye(s)
seq = [1.3, 0.4, 1.2, 1.329, 0.9, 1.1, 1.25]
for x in seq: P = Bt = Btil(s, g0, g1, x)@P
ev = np.sort(np.abs(np.linalg.eigvals(Vi@(np.linalg.multi_dot([Bs(x) for x in seq[::-1]]))@V)))[::-1]
pred = np.sort(np.abs(np.array([np.prod(seq)**i*(1-i*g1)**len(seq) for i in range(s)])))[::-1]
out["triangular_spectrum_identity"] = dict(numeric=list(ev), predicted=list(pred), maxreldiff=float(np.max(np.abs(ev-pred)/np.maximum(pred, 1e-300))))
print(json.dumps(out, indent=1))

