# ---------------- problems ----------------
class Prob: pass
def PR(lam, T=1.0):
    p = Prob(); p.name = f"PR(lam={lam:g})"; p.n = 1; p.T = T
    g = lambda t: np.cos(t)+np.sin(2*t)/2; gp = lambda t: -np.sin(t)+np.cos(2*t)
    p.ex = lambda t: np.array([g(t)]); p.f = lambda t, y: np.array([lam*(y[0]-g(t))+gp(t)])
    p.J = lambda t, y: np.array([[lam]]); p.jvp = lambda t, y, v: lam*v; return p
def LIN(n=24, T=1.0, seed=3):
    rng = np.random.default_rng(seed); p = Prob(); p.name = "LIN-stiff(n=24; real -1..-1e4, pair -100+-400i)"; p.n = n; p.T = T
    lam = -10**np.linspace(0, 4, n-2); D = np.zeros((n, n)); D[:n-2, :n-2] = np.diag(lam)
    D[n-2:, n-2:] = np.array([[-100, 400], [-400, -100]])
    Q, _ = np.linalg.qr(rng.normal(size=(n, n))); A = Q@D@Q.T
    a, b, d = rng.normal(size=n), rng.normal(size=n), rng.normal(size=n)
    ys = lambda t: a*np.cos(t)+b*np.sin(2*t)+d; dys = lambda t: -a*np.sin(t)+2*b*np.cos(2*t)
    p.A = A; p.ex = ys; p.f = lambda t, y: A@(y-ys(t))+dys(t); p.J = lambda t, y: A; p.jvp = lambda t, y, v: A@v; return p
def DIFF(kind="semilinear", n=31, T=1.0):
    dx = 1.0/(n+1); xg = dx*np.arange(1, n+1); p = Prob(); p.n = n; p.T = T
    if kind == "semilinear":
        p.name = "FISHER-KPP semilinear MOL (d=1,r=20,n=31)"; d, r = 1.0, 20.0
        def F(u):
            ue = np.concatenate(([0.5], u, [0.5])); return d*(ue[:-2]-2*ue[1:-1]+ue[2:])/dx**2 + r*u*(1-u)
        def Jm(u):
            Lm = d*(np.diag(-2*np.ones(n))+np.diag(np.ones(n-1), 1)+np.diag(np.ones(n-1), -1))/dx**2; return Lm+np.diag(r*(1-2*u))
    else:
        p.name = "QUASILINEAR diffusion MOL kappa(u)=0.1+2u^2 (n=31, J varies x18)"
        kap = lambda u: 0.1+2*u*u; dkap = lambda u: 4*u
        def F(u):
            ue = np.concatenate(([0.5], u, [0.5])); km = kap(0.5*(ue[:-1]+ue[1:])); return (km[1:]*(ue[2:]-ue[1:-1])-km[:-1]*(ue[1:-1]-ue[:-2]))/dx**2
        def Jm(u):
            ue = np.concatenate(([0.5], u, [0.5])); um = 0.5*(ue[:-1]+ue[1:]); km = kap(um); dk = 0.5*dkap(um)
            J = np.zeros((n, n))
            for i in range(n):
                # F_i=(k_{i+1/2}(u_{i+1}-u_i)-k_{i-1/2}(u_i-u_{i-1}))/dx^2 with ue indices shifted by 1
                kp, km_, dp, dm = km[i+1], km[i], dk[i+1], dk[i]; up, uc, um_ = ue[i+2], ue[i+1], ue[i]
                J[i, i] += (dp*(up-uc)*1 - kp - dm*(uc-um_) - km_)/dx**2
                if i+1 < n: J[i, i+1] += (kp+dp*(up-uc))/dx**2
                if i-1 >= 0: J[i, i-1] += (km_-dm*(uc-um_))/dx**2
                # derivative of k_{i+1/2} wrt u_{i+1}  already included above via dp; wrt u_i via dp (same dk=0.5 dkap) handled in diagonal term
            return J
    ust = lambda t: 0.5+0.45*np.sin(np.pi*xg)*np.cos(3*t); dust = lambda t: -1.35*np.sin(np.pi*xg)*np.sin(3*t)
    p.ex = ust; p.f = lambda t, u: F(u)-F(ust(t))+dust(t)
    def Jf(t, u): return Jm(u)
    p.J = Jf
    def jvp(t, u, v):
        e = 1e-6*(1+np.linalg.norm(u))/max(np.linalg.norm(v), 1e-300); return (F(u+e*v)-F(u-e*v))/(2*e)
    p.jvp = jvp; p.F = F; return p
def check_jac(p, t=0.3):
    y = p.ex(t); J = p.J(t, y); v = np.random.default_rng(1).normal(size=p.n); return float(np.linalg.norm(J@v-p.jvp(t, y, v))/np.linalg.norm(J@v))
# ---------------- full-step amplification (frozen linear problem y'=Jlin y, scheme with T) ----------------
def full_M(meth, Jl, T, h, sg=1.0):
    B, A, g, Th, dL = coefs(meth, sg); s = len(g); n = Jl.shape[0]
    W = np.zeros((s*n, s*n)); R = np.kron(B, np.eye(n))+h*np.kron(A, Jl-T)
    for i in range(s): W[i*n:(i+1)*n, i*n:(i+1)*n] = np.eye(n)-h*g[i]*T
    return np.linalg.solve(W, R)
def rho_full(meth, Jl, T, h, sg=1.0): return float(np.max(np.abs(np.linalg.eigvals(full_M(meth, Jl, T, h, sg)))))
def FOM(Aop, b, rtol, maxit):
    beta = np.linalg.norm(b)
    if beta == 0: return b.copy(), 0
    V = [b/beta]; H = np.zeros((maxit+1, maxit)); x = None
    for k in range(maxit):
        w = Aop(V[k])
        for _ in range(2):
            for i in range(k+1):
                hh = V[i]@w; H[i, k] += hh; w = w-hh*V[i]
        H[k+1, k] = np.linalg.norm(w)
        e1 = np.zeros(k+1); e1[0] = beta; yk = np.linalg.solve(H[:k+1, :k+1], e1)
        res = abs(H[k+1, k]*yk[-1])
        if res <= rtol*beta or H[k+1, k] < 1e-15*beta or k == maxit-1:
            return np.array(V[:k+1]).T@yk, k+1
        V.append(w/H[k+1, k])
# ---------------- integrator ----------------
def integrate(meth, p, N, Tmode=("exact",), grid="uniform", form="W", seed=0, startpert=None, rec_eps=False):
    c, gf = METH[meth]; s = len(c); n = p.n; rng = np.random.default_rng(seed+N)
    amp = 0.0 if grid == "uniform" else (0.09 if grid == "random" else grid[1]); r = 1+amp*rng.uniform(-1, 1, N)
    h = p.T*r/(r.sum()+c[0]*r[0]); t = np.zeros(N+1); t[0] = -c[0]*h[0]
    for m in range(N): t[m+1] = t[m]+h[m]
    Es = rng.normal(size=(n, n)); Es /= np.linalg.norm(Es, 2)
    Jhist = []; stat = dict(J_builds=0, solves=0, matvecs=0, krylov_its=0, eps_max=0.0)
    mode = Tmode[0]; par = Tmode[1] if len(Tmode) > 1 else None
    if mode == "krylov":
        par, kl = (par if isinstance(par, tuple) else (par, 0)); bh = []
    Rew = rng.uniform(-1, 1, size=(n, n))
    hk = h
    tb = t[:N]    # t_0..t_{N-1}
    Y = np.array([p.ex(tb[0]+c[j]*hk[0]) for j in range(s)])
    if startpert: Y = Y+startpert[1]*hk[0]**startpert[0]*(1+np.arange(s))[:, None]
    for m in range(1, N):
        sg = hk[m]/hk[m-1]; hm = hk[m]
        B, A, g, Th, dL = coefs(meth, sg)
        tp = tb[m-1]+c*hk[m-1]; F = np.array([p.f(tp[j], Y[j]) for j in range(s)])
        tJ, yJ = tp[-1], Y[-1]
        if mode == "krylov":
            bh.append((tJ, yJ.copy())); tJb, yJb = bh[max(0, len(bh)-1-kl)]
            Tmv = lambda v: p.jvp(tJb, yJb, v)
        else:
            Jn = p.J(tJ, yJ); stat["J_builds"] += 1; Jhist.append(Jn)
            if mode == "exact": T = Jn
            elif mode == "lag": T = Jhist[max(0, len(Jhist)-1-par)]
            elif mode == "scale": T = par*Jn
            elif mode == "pert": T = Jn+par*np.linalg.norm(Jn, 2)*Es
            elif mode == "pertew": T = Jn*(1+par*Rew)
            elif mode == "diag": T = np.diag(np.diag(Jn))
            elif mode == "absrow": T = -np.diag(np.abs(Jn).sum(axis=1))
            elif mode == "zero": T = np.zeros_like(Jn)
            else: raise ValueError(mode)
            if rec_eps and n > 1:
                try: stat["eps_max"] = max(stat["eps_max"], float(np.max(np.abs(1-np.linalg.eigvals(np.linalg.solve(T, Jn))))))
                except Exception: pass
            Tmv = lambda v: T@v
        Ynew = np.zeros_like(Y)
        if form == "W":
            TY = np.array([Tmv(Y[j]) for j in range(s)]); stat["matvecs"] += s if mode == "krylov" else 0
            rhs = B@Y+hm*(A@(F-TY))
            for i in range(s):
                if mode == "krylov":
                    x, its = FOM(lambda v: v-hm*g[i]*Tmv(v), rhs[i], par, n+1); Ynew[i] = x; stat["krylov_its"] += its; stat["matvecs"] += its
                else:
                    Ynew[i] = np.linalg.solve(np.eye(n)-hm*g[i]*T, rhs[i])
                stat["solves"] += 1
        else:   # correction form (6.1): (I-h g_i T)(Y_i - (Theta Y)_i) = g_i [Theta (h f(Y_prev) - sigma E Y_prev)]_i
            Yt = Th@Y; rhs = g[:, None]*(Th@(hm*F-sg*(dL@Y)))   # E = nodal differentiation matrix
            for i in range(s):
                if mode == "krylov":
                    x, its = FOM(lambda v: v-hm*g[i]*Tmv(v), rhs[i], par, n+1); stat["krylov_its"] += its; stat["matvecs"] += its
                else:
                    x = np.linalg.solve(np.eye(n)-hm*g[i]*T, rhs[i])
                Ynew[i] = Yt[i]+x; stat["solves"] += 1
        Y = Ynew
        if not np.all(np.isfinite(Y)) or np.abs(Y).max() > 1e8: return np.inf, stat
    tl = tb[N-1]; hl = hk[N-1]
    err = max(np.abs(Y[j]-p.ex(tl+c[j]*hl)).max() for j in range(s))
    return float(err), stat
def orders(meth, p, Ns=(16, 32, 64, 128), **kw):
    e = [integrate(meth, p, N, **kw)[0] for N in Ns]
    o = [None if (not np.isfinite(e[i]) or not np.isfinite(e[i+1]) or e[i+1] == 0 or e[i] == 0) else float(np.log2(e[i]/e[i+1])) for i in range(len(Ns)-1)]
    return e, o
