    if not ok.any(): return None
    i0 = int(np.argmax(ok)); i1 = len(ok)-1-int(np.argmax(ok[::-1]))
    def refine(a, b):                        # a not ok, b ok
        for _ in range(14):
            m = 0.5*(a+b)
            if supM(meth, m, sg, ang) <= 1+1e-9: b = m
            else: a = m
        return b
    lo = refine(ks[i0-1], ks[i0]) if i0 > 0 else ks[0]
    hi_ok = ks[i1]
