# PW04 common library (literature + exact/numeric replay only).  python3 -I; numpy/scipy/mpmath.
import mpmath as mp, numpy as np, json, sys, hashlib
mp.mp.dps = 80
MPF = mp.mpf

# ---------- nodes / parameters ----------
def cheb_nodes(s):                      # BIT (5.8): c_i = cos((2s+1-2i)pi/(2s)) / cos(pi/(2s))
    return [mp.cos((2*s+1-2*i)*mp.pi/(2*s))/mp.cos(mp.pi/(2*s)) for i in range(1, s+1)]
def sigma_sup(s):                       # BIT Remark 2.1 : (s-2) x^(s-1) - (s-1) x^(s-2) - 1 = 0, root > 1
    f = lambda x: (s-2)*x**(s-1) - (s-1)*x**(s-2) - 1
    lo, hi = MPF(1), MPF(4)             # f(1) = -2 < 0 ; f(4) > 0 for s>=3
    for _ in range(300):
        mid = (lo+hi)/2
        if f(mid) > 0: hi = mid
        else: lo = mid
    return (lo+hi)/2
def g1_of(s): return 1 - 1/sigma_sup(s)  # (1-g1) sigma_sup = 1

# ---------- Route 1: BIT matrix formulas (2.4),(2.5) : Theta = V S P V^-1, E = V D F0^T V^-1, B = Theta - sigma A E ----------
def vander(c):
    s = len(c); return mp.matrix([[c[i]**j for j in range(s)] for i in range(s)])
def route1(c, gam, sg):
    s = len(c); V = vander(c); Vi = V**-1
    S = mp.diag([sg**j for j in range(s)])
    P = mp.matrix(s, s)
    for i in range(s):
        for j in range(i, s): P[i, j] = mp.binomial(j, i)
    D = mp.diag([k+1 for k in range(s)])
    F0 = mp.matrix(s, s)
    for i in range(1, s): F0[i, i-1] = 1
    Th = V*S*P*Vi
    E = V*D*F0.T*Vi
    G = mp.diag(gam)
    Gm = -G*Th; A = -Gm
    B = Th - sg*A*E
    return dict(Theta=Th, Gamma=Gm, A=A, B=B, E=E)

# ---------- Route 2: direct Lagrange/polynomial form of Gamma(s),AB(s)  (BIT (3.1)); no Vandermonde inverse ----------
def lag(c, j, x):
    r = MPF(1)
    for k in range(len(c)):
        if k != j: r *= (x-c[k])/(c[j]-c[k])
    return r
def dlag(c, j, x):
    s = len(c); tot = MPF(0)
    for m in range(s):
        if m == j: continue
        t = 1/(c[j]-c[m])
        for k in range(s):
            if k != j and k != m: t *= (x-c[k])/(c[j]-c[k])
        tot += t
    return tot
def route2(c, gam, sg):
    s = len(c); Th = mp.matrix(s, s); B = mp.matrix(s, s); A = mp.matrix(s, s)
    for i in range(s):
        x = 1+sg*c[i]
        for j in range(s):
            Th[i, j] = lag(c, j, x)
            A[i, j] = gam[i]*Th[i, j]                       # A = -Gamma = G Theta
            B[i, j] = Th[i, j] - gam[i]*sg*dlag(c, j, x)    # (3.1) AB: b_ij p(c_j) = p(1+sg c_i) - gam_i sg p'(1+sg c_i)
    return dict(Theta=Th, A=A, B=B)

# ---------- Route 3: BIT (2.15)  B~ = (I - g1 Dhat - g0 F0^T Dhat) S P, B = V B~ V^-1 ----------
def route3(c, g0, g1, sg):
    s = len(c); V = vander(c); Vi = V**-1
    S = mp.diag([sg**j for j in range(s)])
    P = mp.matrix(s, s)
    for i in range(s):
        for j in range(i, s): P[i, j] = mp.binomial(j, i)
    Dh = mp.diag([k for k in range(s)])
    F0 = mp.matrix(s, s)
    for i in range(1, s): F0[i, i-1] = 1
    Bt = (mp.eye(s) - g1*Dh - g0*F0.T*Dh)*S*P
    return dict(Btilde=Bt, B=V*Bt*Vi, V=V, Vi=Vi)

def mdiff(X, Y): return max(abs(X[i, j]-Y[i, j]) for i in range(X.rows) for j in range(X.cols))
def mp2np(M): return np.array([[float(M[i, j]) for j in range(M.cols)] for i in range(M.rows)])

# ---------- (4.7) superconvergence condition on g0 ----------
def v_tilde(s, g0, g1):                 # left eigvec (size s+1) of the (s+1)x(s+1) triangular B~(sigma=1), eigenvalue 1, v1=1
    n = s+1
    S = mp.eye(n); P = mp.matrix(n, n)
    for i in range(n):
        for j in range(i, n): P[i, j] = mp.binomial(j, i)
    Dh = mp.diag([k for k in range(n)]); F0 = mp.matrix(n, n)
    for i in range(1, n): F0[i, i-1] = 1
    Bt = (mp.eye(n) - g1*Dh - g0*F0.T*Dh)*S*P
    v = [MPF(0)]*n; v[0] = MPF(1)
    for j in range(1, n):
        acc = sum(v[i]*Bt[i, j] for i in range(j))
        v[j] = acc/(1-Bt[j, j])           # v_j (B~_jj - 1) + sum_{i<j} v_i B~_ij = 0
    return v
def resid47(c, g0, g1):                  # (4.7): v~ . (phi_0..phi_{s-1}, 1)
    s = len(c); v = v_tilde(s, g0, g1)
    # node polynomial coefficients phi_0..phi_s (phi_s = 1)
    co = [MPF(1)]
    for ci in c:
        new = [MPF(0)]*(len(co)+1)
        for k, a in enumerate(co): new[k+1] += a; new[k] -= ci*a
        co = new
    return sum(v[k]*co[k] for k in range(s+1))
def g0_roots_47(c, g1, lo=None, hi=4, n=800):
    # roots of a polynomial in g0 (degree <= s): interpolate exactly through s+1 points, then polyroots
    s = len(c); pts = [MPF(k)/2 for k in range(s+1)]
    vals = [resid47(c, p, g1) for p in pts]
    # Newton-form -> monomial via solving Vandermonde
    Vm = mp.matrix([[p**k for k in range(s+1)] for p in pts]); co = mp.lu_solve(Vm, mp.matrix(vals))
    rts = mp.polyroots([co[k] for k in range(s, -1, -1)], maxsteps=500, extraprec=400)
    return sorted([mp.re(r) for r in rts if abs(mp.im(r)) < mp.mpf(10)**-40], key=lambda x: x)
# alternative route for g0 :  v^T w = 0 with v left eigvec (v^T 1 = 1) of nodal B(1) and w_i = phi(1+c_i) - gam_i phi'(1+c_i)   (BIT (4.5))
def resid_nodal(c, g0, g1):
    s = len(c); gam = [g0+g1*ci for ci in c]
    B = route2(c, gam, MPF(1))['B']
    Bn = mp2np(B)
    # left eigenvector for eigenvalue 1 by exact solve in mp:  v^T (B - I) = 0, v^T 1 = 1
    M = (B - mp.eye(s)).T
    M2 = mp.matrix(s, s)
    for i in range(s-1):
        for j in range(s): M2[i, j] = M[i, j]
    for j in range(s): M2[s-1, j] = 1
    rhs = mp.matrix([0]*(s-1)+[1]); v = mp.lu_solve(M2, rhs)
    phi = lambda x: mp.fprod([x-ci for ci in c])
    dphi = lambda x: mp.fsum(mp.fprod([x-ck for k, ck in enumerate(c) if k != m]) for m in range(s))
    w = [phi(1+c[i]) - gam[i]*dphi(1+c[i]) for i in range(s)]
    return mp.fsum(v[i]*w[i] for i in range(s))

# ---------- numpy (double) coefficient evaluation for experiments ----------
def lag_np(c, x):
    s = len(c); L = np.ones((len(x), s)); dL = np.zeros((len(x), s))
    for j in range(s):
        for k in range(s):
            if k != j: L[:, j] *= (x-c[k])/(c[j]-c[k])
        for m in range(s):
            if m == j: continue
            t = np.ones(len(x))/(c[j]-c[m])
            for k in range(s):
                if k != j and k != m: t *= (x-c[k])/(c[j]-c[k])
            dL[:, j] += t
    return L, dL
def coef_np(c, gam, sg):
    c = np.asarray(c, float); gam = np.asarray(gam, float)
    x = 1+sg*c; L, dL = lag_np(c, x)
    A = gam[:, None]*L; B = L - gam[:, None]*sg*dL
    return B, A
def alpha_deg(B, gam, nphi=721, nr=500, rlo=-6, rhi=10):
    rs = np.logspace(rlo, rhi, nr); g = np.asarray(gam, float)
    def f(p):
        z = rs*np.exp(1j*(np.pi-np.radians(p)))
        M = (1.0/(1.0-z[:, None]*g[None, :]))[:, :, None]*B[None, :, :]
        return float(np.max(np.abs(np.linalg.eigvals(M))))
    prev = 0.0
    for p in np.linspace(0, 90, nphi):
        if f(p) >= 1+1e-13:
            lo, hi = prev, p
            for _ in range(40):
                m = 0.5*(lo+hi)
                if f(m) >= 1+1e-13: hi = m
                else: lo = m
            return lo
        prev = p
    return 90.0
def rho(M): return float(np.max(np.abs(np.linalg.eigvals(M))))

# ---------- method definitions ----------
P26 = dict(c=["-1.702","-0.51","-0.195797762","0.155193392","0.755672784","1"],
  g0=["0.214789562","0.249182503","0.237832565","0.245204742","0.353848357"],
  g1=["0.566334104","0.496228487","0.518584061","0.498857638","0.502412430"])   # APNUM 48 PPSW2-6 (PW03A/PW03B recovery)
def gam_ppsw2(c, g0, g1, sg):            # APNUM (3.8) i<s ; (3.6) i=s
    s = len(c); g = [g0[i]/(1+sg*g1[i]) for i in range(s-1)]
    g.append(1/(sg*sum(1/(1+sg-cj) for cj in c))); return g
def mipeer_params(s, g0=None):
    c = cheb_nodes(s); g1 = g1_of(s)
    if g0 is None:
        rts = g0_roots_47(c, g1); lb = -g1*min(c)
        g0 = [r for r in rts if r > lb][0]
    return c, g0, g1
def sha(b): return hashlib.sha256(b if isinstance(b, bytes) else b.encode()).hexdigest()
# PW04-M5 core (prototype harness, scratch only): peer-W step with approximate T, synthetic problems, stability/orders.
import scipy.linalg as sla
cm6 = np.array([float(x) for x in cheb_nodes(6)]); _c6, _g0, _g1 = mipeer_params(6); G0M, G1M = float(_g0), float(_g1)
c26 = np.array([float(x) for x in P26["c"]]); g026 = [float(x) for x in P26["g0"]]; g126 = [float(x) for x in P26["g1"]]
METH = {"mipeer6": (cm6, lambda sg: G0M+G1M*cm6), "PPSW2-6": (c26, lambda sg: np.array(gam_ppsw2(list(c26), g026, g126, sg)))}
_cc = {}
def coefs(meth, sg):
    k = (meth, round(float(sg), 10))
    if k not in _cc:
        c, gf = METH[meth]; g = gf(sg); B, A = coef_np(c, g, sg)
        L, dL = lag_np(c, c)         # nodal differentiation matrix E_ij = l_j'(c_i)
        x = 1+sg*c; Th, _ = lag_np(c, x)
        _cc[k] = (B, A, np.asarray(g, float), Th, dL)
    return _cc[k]
# ---------------- problems ----------------
class Prob: pass
def PR(lam, T=1.0):
    p = Prob(); p.name = f"PR(lam={lam:g})"; p.n = 1; p.T = T
    g = lambda t: np.cos(t)+np.sin(2*t)/2; gp = lambda t: -np.sin(t)+np.cos(2*t)
    p.ex = lambda t: np.array([g(t)]); p.f = lambda t, y: np.array([lam*(y[0]-g(t))+gp(t)])
    p.J = lambda t, y: np.array([[lam]]); p.jvp = lambda t, y, v: lam*v; return p
def LIN(n=24, T=1.0, seed=3):
    rng = np.random.default_rng(seed); p = Prob(); p.name = "LIN-stiff(n=24; real -1..-1e4, pair -100+-400i)"; p.n = n; p.T = T
    lam = -10**np.linspace(0, 4, n-2); D = np.zeros((n, n)); D[:n-2, :n-2] = np.diag(lam)
    D[n-2:, n-2:] = np.array([[-100, 400], [-400, -100]])
    Q, _ = np.linalg.qr(rng.normal(size=(n, n))); A = Q@D@Q.T
    a, b, d = rng.normal(size=n), rng.normal(size=n), rng.normal(size=n)
    ys = lambda t: a*np.cos(t)+b*np.sin(2*t)+d; dys = lambda t: -a*np.sin(t)+2*b*np.cos(2*t)
    p.A = A; p.ex = ys; p.f = lambda t, y: A@(y-ys(t))+dys(t); p.J = lambda t, y: A; p.jvp = lambda t, y, v: A@v; return p
def DIFF(kind="semilinear", n=31, T=1.0):
    dx = 1.0/(n+1); xg = dx*np.arange(1, n+1); p = Prob(); p.n = n; p.T = T
    if kind == "semilinear":
        p.name = "FISHER-KPP semilinear MOL (d=1,r=20,n=31)"; d, r = 1.0, 20.0
        def F(u):
            ue = np.concatenate(([0.5], u, [0.5])); return d*(ue[:-2]-2*ue[1:-1]+ue[2:])/dx**2 + r*u*(1-u)
        def Jm(u):
            Lm = d*(np.diag(-2*np.ones(n))+np.diag(np.ones(n-1), 1)+np.diag(np.ones(n-1), -1))/dx**2; return Lm+np.diag(r*(1-2*u))
    else:
        p.name = "QUASILINEAR diffusion MOL kappa(u)=0.1+2u^2 (n=31, J varies x18)"
        kap = lambda u: 0.1+2*u*u; dkap = lambda u: 4*u
        def F(u):
            ue = np.concatenate(([0.5], u, [0.5])); km = kap(0.5*(ue[:-1]+ue[1:])); return (km[1:]*(ue[2:]-ue[1:-1])-km[:-1]*(ue[1:-1]-ue[:-2]))/dx**2
        def Jm(u):
            ue = np.concatenate(([0.5], u, [0.5])); um = 0.5*(ue[:-1]+ue[1:]); km = kap(um); dk = 0.5*dkap(um)
            J = np.zeros((n, n))
            for i in range(n):
                # F_i=(k_{i+1/2}(u_{i+1}-u_i)-k_{i-1/2}(u_i-u_{i-1}))/dx^2 with ue indices shifted by 1
                kp, km_, dp, dm = km[i+1], km[i], dk[i+1], dk[i]; up, uc, um_ = ue[i+2], ue[i+1], ue[i]
                J[i, i] += (dp*(up-uc)*1 - kp - dm*(uc-um_) - km_)/dx**2
                if i+1 < n: J[i, i+1] += (kp+dp*(up-uc))/dx**2
                if i-1 >= 0: J[i, i-1] += (km_-dm*(uc-um_))/dx**2
                # derivative of k_{i+1/2} wrt u_{i+1}  already included above via dp; wrt u_i via dp (same dk=0.5 dkap) handled in diagonal term
            return J
    ust = lambda t: 0.5+0.45*np.sin(np.pi*xg)*np.cos(3*t); dust = lambda t: -1.35*np.sin(np.pi*xg)*np.sin(3*t)
    p.ex = ust; p.f = lambda t, u: F(u)-F(ust(t))+dust(t)
    def Jf(t, u): return Jm(u)
    p.J = Jf
    def jvp(t, u, v):
        e = 1e-6*(1+np.linalg.norm(u))/max(np.linalg.norm(v), 1e-300); return (F(u+e*v)-F(u-e*v))/(2*e)
    p.jvp = jvp; p.F = F; return p
def check_jac(p, t=0.3):
    y = p.ex(t); J = p.J(t, y); v = np.random.default_rng(1).normal(size=p.n); return float(np.linalg.norm(J@v-p.jvp(t, y, v))/np.linalg.norm(J@v))
# ---------------- full-step amplification (frozen linear problem y'=Jlin y, scheme with T) ----------------
def full_M(meth, Jl, T, h, sg=1.0):
    B, A, g, Th, dL = coefs(meth, sg); s = len(g); n = Jl.shape[0]
    W = np.zeros((s*n, s*n)); R = np.kron(B, np.eye(n))+h*np.kron(A, Jl-T)
    for i in range(s): W[i*n:(i+1)*n, i*n:(i+1)*n] = np.eye(n)-h*g[i]*T
    return np.linalg.solve(W, R)
def rho_full(meth, Jl, T, h, sg=1.0): return float(np.max(np.abs(np.linalg.eigvals(full_M(meth, Jl, T, h, sg)))))
def FOM(Aop, b, rtol, maxit):
    beta = np.linalg.norm(b)
    if beta == 0: return b.copy(), 0
    V = [b/beta]; H = np.zeros((maxit+1, maxit)); x = None
    for k in range(maxit):
        w = Aop(V[k])
        for _ in range(2):
            for i in range(k+1):
                hh = V[i]@w; H[i, k] += hh; w = w-hh*V[i]
        H[k+1, k] = np.linalg.norm(w)
        e1 = np.zeros(k+1); e1[0] = beta; yk = np.linalg.solve(H[:k+1, :k+1], e1)
        res = abs(H[k+1, k]*yk[-1])
        if res <= rtol*beta or H[k+1, k] < 1e-15*beta or k == maxit-1:
            return np.array(V[:k+1]).T@yk, k+1
        V.append(w/H[k+1, k])
# ---------------- integrator ----------------
def integrate(meth, p, N, Tmode=("exact",), grid="uniform", form="W", seed=0, startpert=None, rec_eps=False):
    c, gf = METH[meth]; s = len(c); n = p.n; rng = np.random.default_rng(seed+N)
    amp = 0.0 if grid == "uniform" else (0.09 if grid == "random" else grid[1]); r = 1+amp*rng.uniform(-1, 1, N)
    h = p.T*r/(r.sum()+c[0]*r[0]); t = np.zeros(N+1); t[0] = -c[0]*h[0]
    for m in range(N): t[m+1] = t[m]+h[m]
    Es = rng.normal(size=(n, n)); Es /= np.linalg.norm(Es, 2)
