def PRw(lam, w, T=2.0):
    p = Prob(); p.name = f"PR(lam={lam:g},w={w})"; p.n = 1; p.T = T
    g = lambda t: np.cos(w*t)+np.sin(2*w*t)/2; gp = lambda t: -w*np.sin(w*t)+w*np.cos(2*w*t)
    p.ex = lambda t: np.array([g(t)]); p.f = lambda t, y: np.array([lam*(y[0]-g(t))+gp(t)]); p.J = lambda t, y: np.array([[lam]]); p.jvp = lambda t, y, v: lam*v; return p
